func SignBatch(messages []string) (string, error) {
    n := C.size_t(len(messages))
    cMessages := make([]*C.char, n)
    for i, msg := range messages {
        cMessages[i] = C.CString(msg)
        defer C.free(unsafe.Pointer(cMessages[i]))
    }

    var cJson *C.char
    ret := C.sign_batch(&cMessages[0], n, &cJson)
    if ret != 0 {
        return "", errors.New("sign_batch failed")
    }

    result := C.GoString(cJson)
    C.free_json(cJson)
    return result, nil
}
